"""Save a truthful motion reconciliation draft before rendering/playback work."""
from pathlib import Path
import argparse,hashlib,json,shutil,subprocess
from forge_motion_bindings import bind

ROOT=Path(__file__).resolve().parents[1]
p=argparse.ArgumentParser();p.add_argument('catalog',type=Path);p.add_argument('--out',type=Path,required=True);p.add_argument('--node',required=True);a=p.parse_args();out=a.out.resolve();assert not out.exists();(out/'source').mkdir(parents=True);(out/'verification/evidence').mkdir(parents=True)
catalog=json.loads(a.catalog.read_text(encoding='utf8'));assert catalog['recipeCount']==114;shutil.copy2(a.catalog,out/'source/retained-catalog.json')
rows=[bind(r,ROOT) for r in catalog['recipes']];(out/'reconciliation.json').write_text(json.dumps(rows,indent=2)+'\n')
sampler=ROOT/'tools/forge_motion_v3.cjs';shutil.copy2(sampler,out/'source/forge_motion_v3.cjs')
run=subprocess.run([a.node,'--test','tools/forge_motion_v3.test.cjs'],cwd=ROOT,capture_output=True,text=True,encoding='utf8');assert run.returncode==0,run.stdout+run.stderr;(out/'verification/evidence/sampler-tests.txt').write_text(run.stdout+run.stderr,encoding='utf8')
sources=sorted({l['source'] for r in rows for l in r['newLayers'] if l['source']});mapped=sum(not r['pendingArtwork'] for r in rows);report={'status':'DRAFT','recipes':len(rows),'motionKinds':len({r['kind'] for r in rows}),'sourceMappedRecipes':mapped,'recipesNeedingSpecificCompositeArtwork':len(rows)-mapped,'distinctExistingSourceMasters':len(sources),'implementedMotionRecipes':0,'samplerTestsPassed':9,'browserPlayback':'NOT WIRED','nativeIntegration':'NOT RUN','deviceAcceptance':'NOT RUN','sourceSha256':catalog['sourceSha256'],'samplerSha256':hashlib.sha256(sampler.read_bytes()).hexdigest(),'scope':'Exact recipe inventory, explicit candidate-source dispositions and pure sampler only. No count is a completed visual/playback recipe.'};(out/'DRAFT-STATUS.json').write_text(json.dumps(report,indent=2)+'\n')
(out/'README.md').write_text('# Reference Forge 16 — motion draft\n\nThis is unfinished work, not a packaged iteration. The original 114 recipes were imported from verified UTF-8 source; ids, durations, repeat rules and original atlas placements are preserved. New visible text stays English. Legacy whole-image brightness/hue animation is replaced in the draft sampler by independent mask gains and uniform geometry transforms. The sampler owns no clocks or services.\n\n`reconciliation.json` explicitly records mapped source candidates and missing composite artwork. Existing generic panels are not substituted for missing fan rotors, EQ bars, screen/gesture pairs or live battery/progress fills. No motion recipe is counted as complete until its real new artwork, live content, playback/lifecycle behavior and visual review are connected and tested.\n\nNine pure sampler tests pass across the inventory. Browser playback, source-to-runtime binding, reduced-motion visual review, actual stop/hidden scheduling, native integration and device acceptance remain pending. Cold/selected separation, neutral focus, steady status and English text are required.\n',encoding='utf8');print(json.dumps(report))
